<script setup lang="ts">
import { Head, useForm } from '@inertiajs/vue3';
import { computed, ref } from 'vue';
import AccountLayout from '../../../layouts/AccountLayout.vue';
import type { Taxonomy, CatalogStatus } from '../../../types/catalog';
import StatusBadge from '../../../components/StatusBadge.vue';
const props = defineProps<{ kind: 'categories' | 'brands'; entries: Taxonomy[]; canManage: boolean }>();
const selected = ref<number | null>(null);
const form = useForm({ name: '', slug: '', description: '', status: 'draft' as CatalogStatus, parent_id: null as number | null });
const title = props.kind === 'categories' ? 'Categorías y subcategorías' : 'Marcas';
// Only the table rows are filtered: parent names and the parent selector still use every entry.
const showDemo = ref(false);
const demoCount = computed(() => props.entries.filter(e => e.is_demo).length);
const multiplier = (units: number) => '×' + (units / 10000).toLocaleString('es-CR', { minimumFractionDigits: 2, maximumFractionDigits: 4 });
const visibleEntries = computed(() => showDemo.value ? props.entries : props.entries.filter(e => !e.is_demo));
function edit(item?: Taxonomy) { selected.value = item?.id ?? null; form.clearErrors(); form.name = item?.name ?? ''; form.slug = item?.slug ?? ''; form.description = item?.description ?? ''; form.status = item?.status ?? 'draft'; form.parent_id = item?.parent_id ?? null; }
function submit() { form.transform(data => props.kind === 'brands' ? { name: data.name, slug: data.slug, description: data.description, status: data.status } : data); if (selected.value) form.put(`/admin/catalog/${props.kind}/${selected.value}`); else form.post(`/admin/catalog/${props.kind}`, { onSuccess: () => edit() }); }
</script>
<template><Head :title="title"/><AccountLayout :title="title" section="admin"><p class="muted">{{ canManage ? 'Archivar conserva la información y oculta los productos relacionados.' : 'Acceso de consulta. Solo un administrador puede modificar el catálogo.' }}</p><p v-if="demoCount" class="demo-toggle muted"><template v-if="!showDemo">{{ demoCount }} {{ demoCount === 1 ? 'categoría de demostración oculta' : 'categorías de demostración ocultas' }}. <button type="button" class="quiet-link" @click="showDemo = true">Mostrar</button></template><template v-else>Mostrando también categorías de demostración. <button type="button" class="quiet-link" @click="showDemo = false">Ocultarlas</button></template></p><div class="catalog-admin-grid"><div class="table-wrap"><table><thead><tr><th>Nombre</th><th>Estado</th><template v-if="kind === 'categories'"><th class="num">Productos</th><th>Multiplicador</th></template><th>Acción</th></tr></thead><tbody><tr v-for="item in visibleEntries" :key="item.id"><td class="tree-name" :style="{ '--depth': item.depth ?? 0 }"><span v-if="item.depth" class="tree-branch" aria-hidden="true">└</span>{{ item.name }}<small class="block muted">{{ item.slug }}</small></td><td><StatusBadge :status="item.status"/></td><template v-if="kind === 'categories'"><td class="num">{{ item.products_total }}<small v-if="item.products_total !== item.products_direct" class="block muted">{{ item.products_direct }} propios</small></td><td class="tree-rule"><template v-if="item.pricing">{{ multiplier(item.pricing.units) }}<small class="block muted">{{ item.pricing.inherited ? `hereda de ${item.pricing.from}` : item.pricing.rule }}</small></template><span v-else class="muted">Sin regla</span></td></template><td><button class="quiet-link" @click="edit(item)">{{ canManage ? 'Editar' : 'Consultar' }}</button></td></tr><tr v-if="!entries.length"><td :colspan="kind === 'categories' ? 5 : 3">Sin registros todavía.</td></tr></tbody></table></div><form class="info-card compact-form" @submit.prevent="submit"><h2>{{ selected ? 'Detalle' : 'Nuevo registro' }}</h2><fieldset :disabled="!canManage || form.processing"><label>Nombre<input v-model="form.name" required maxlength="120"></label><label>Slug<input v-model="form.slug" required pattern="[a-z0-9]+(-[a-z0-9]+)*" maxlength="160"><small>Identificador para URL, por ejemplo: tarjetas-graficas.</small></label><label v-if="kind === 'categories'">Categoría superior<select v-model="form.parent_id"><option :value="null">Sin superior</option><option v-for="parent in entries.filter(p => p.id !== selected)" :key="parent.id" :value="parent.id">{{ '— '.repeat(parent.depth ?? 0) }}{{ parent.name }}</option></select></label><label>Descripción<textarea v-model="form.description" maxlength="3000"/></label><label>Estado<select v-model="form.status"><option value="draft">Borrador</option><option value="published">Publicado</option><option value="archived">Archivado</option></select></label><p v-for="(error, key) in form.errors" :key="key" class="field-error" role="alert">{{ error }}</p><button v-if="canManage" class="button full" :disabled="form.processing">Guardar</button></fieldset><button v-if="canManage && selected" type="button" class="quiet-link mt-4" @click="edit()">Crear otro registro</button></form></div></AccountLayout></template>
